import React, { createContext, useState, useEffect } from 'react';

const TooltipContext = createContext();

const TooltipProvider = ({ children }) => {
  const [tooltip, setTooltip] = useState(null);
  const [tooltipPosition, setTooltipPosition] = useState(null);

  useEffect(() => {
    const closeTooltip = () => {
      setTooltip(null);
      setTooltipPosition(null);
    };

    document.addEventListener('click', closeTooltip);

    return () => {
      document.removeEventListener('click', closeTooltip);
    };
  }, []);

  return (
    <TooltipContext.Provider value={{ tooltip, setTooltip, tooltipPosition, setTooltipPosition }}>
      {children}
    </TooltipContext.Provider>
  );
};

const Tooltip = () => {
  const { tooltip, setTooltip, tooltipPosition, setTooltipPosition } = React.useContext(TooltipContext);

  const handleOpenTooltip = (position) => {
    setTooltipPosition(position);
    setTooltip(true);
  };

  const handleCloseTooltip = () => {
    setTooltip(false);
    setTooltipPosition(null);
  };

  return (
    <div>
      <button onClick={() => handleOpenTooltip('top')}>Open Tooltip Top</button>
      <button onClick={() => handleOpenTooltip('bottom')}>Open Tooltip Bottom</button>
      <button onClick={() => handleOpenTooltip('left')}>Open Tooltip Left</button>
      <button onClick={() => handleOpenTooltip('right')}>Open Tooltip Right</button>
      {tooltip && (
        <div
          className="tooltip"
          style={{
            position: 'absolute',
            top: tooltipPosition === 'top' ? '100%' : null,
            bottom: tooltipPosition === 'bottom' ? '100%' : null,
            left: tooltipPosition === 'left' ? '100%' : null,
            right: tooltipPosition === 'right' ? '100%' : null,
          }}
        >
          <span>Tooltip content</span>
          <button onClick={handleCloseTooltip}>Close</button>
        </div>
      )}
    </div>
  );
};

const App = () => {
  return (
    <TooltipProvider>
      <Tooltip />
    </TooltipProvider>
  );
};
```

