                    attributes.heading
                ),
                wp.element.createElement(
                    'p',
                    null,
                    attributes.paragraph
                ),
                wp.element.createElement(
                    'img',
                    { src: attributes.image, alt: 'Image' }
                )
            );
        }
    }
} );
