            System.out.println("You go back home and forget about the cave.");
        } else {
            System.out.println("Invalid choice. Please try again.");
        }
    }

    // Method to get a valid choice from the user
    public static int getValidChoice(Scanner scanner, int maxChoices) {
        while (true) {
            try {
                System.out.print("Enter your choice (1-" + maxChoices + "): ");
                int choice = scanner.nextInt();
                if (choice >= 1 && choice <= maxChoices) {
                    return choice;
                } else {
                    System.out.println("Invalid choice. Please try again.");
                }
            } catch (Exception e) {
                System.out.println("Invalid input. Please enter a number.");
                scanner.next(); // Clear the invalid input
            }
        }
    }
}
